        return {"ok": False, "error": "bad member id"}

    status = raw_member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    if status not in _VALID_STATUSES:
        return {"ok": False, "error": "unknown status"}
    if raw_member["tier"] not in _VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}

    if status == "active":
        fee = TIER_FEES[raw_member["tier"]]
        return _check_payment(raw_member, raw_payment, fee, "renewed")

    if status == "lapsed":
